    output f
);

    // Internal signals for decoded address bits
    wire x3 = x[3];
    wire x2 = x[2];
    wire x1 = x[1];
    wire x0 = x[0];

    // Implement the function derived from the K-map:
    // f = x3' & x2' & x1 & x0'   (m1)
    //    | x3' & x2  & x1' & x0'  (m4)
    //    | x3  & x2  & x1         (m12)
    //    | x3  & x2  & x1' & x0'  (m13)
    //    | x3  & x2' & x1 & x0    (m14)
