module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    // State encoding: 4 states to cover the sequence 1101 detection
    typedef enum logic [1:0] {
        S_IDLE   = 2'b00, // Waiting for the first '1'
        S_1      = 2'b01, // Matched first '1'
        S_10     = 2'b10, // Matched '10' (second '1' and '0')
        S_101    = 2'b11  // Matched '101' (waiting for final '1')
    } state_t;

    state_t state, next_state;

    // State register (synchronous reset, active high)
    always_ff @(posedge clk) begin
        if (reset)
            state <= S_IDLE;
        else
            state <= next_state;
    end

    // Next-state logic (combinational)
    always_comb begin
        case (state)
            S_IDLE: begin
                if (data == 1'b1)
                    next_state = S_1;
                else
                    next_state = S_IDLE;
            end
            S_1: begin
                if (data == 1'b1)
                    next_state = S_10; // Second '1' received, expecting '0'
                else
                    next_state = S_IDLE; // Sequence broken, go back to idle
            end
            S_10: begin
                if (data == 1'b1)
                    next_state = S_101; // Received '101', expecting final '1'
                else
                    next_state = S_IDLE; // Sequence broken
            end
            S_101: begin
                if (data == 1'b1)
                    next_state = S_101; // Final '1' received, stay in accepting state
                else
                    next_state = S_IDLE; // Sequence broken
            end
            default: next_state = S_IDLE;
        endcase
    end

    // Output logic
    // start_shifting is set to 1 once the sequence 1101 is detected and stays 1 until reset
    assign start_shifting = (state == S_101);

endmodule

