module TopModule (
    input  [3:0] in,
    output [3:0] out_both,
    output [3:0] out_any,
    output [3:0] out_different
);

    // out_both[i] = in[i] & in[i+1] for i = 0..2
    // out_both[3] is not needed (no left neighbour for in[3])
    assign out_both[0] = in[0] & in[1];
    assign out_both[1] = in[1] & in[2];
    assign out_both[2] = in[2] & in[3];
    assign out_both[3] = 1'b0;          // unused, driven low

    // out_any[i] = in[i] | in[i-1] for i = 1..3
    // out_any[0] is not needed (in[0] has no right neighbour)
    assign out_any[1] = in[1] | in[0];
    assign out_any[2] = in[2] | in[1];
    assign out_any[3] = in[3] | in[2];
    assign out_any[0] = 1'b0;          // unused, driven low

    // out_different[i] = in[i] ^ in[i-1] with wrap-around
    // i=3: neighbour is in[0]; i=2: neighbour is in[3]... wait.
    // Specification: out_different[2] compares in[2] with in[3] (left neighbour of in[2] is in[3]).
    // Treat vector as wrapping: in[3]'s left neighbour is in[0].
    // Therefore:
    //   out_different[3] = in[3] ^ in[0]
    //   out_different[2] = in[2] ^ in[3]
    //   out_different[1] = in[1] ^ in[2]
    //   out_different[0] = in[0] ^ in[1]  (left neighbour of in[0] is in[1] due to wrap)
    assign out_different[3] = in[3] ^ in[0];
    assign out_different[2] = in[2] ^ in[3];
    assign out_different[1] = in[1] ^ in[2];
    assign out_different[0] = in[0] ^ in[1];

endmodule

