module TopModule (
    input  clk,
    input  x,
    output z
);

    // Internal signals for the three D flip-flops
    reg q0, q1, q2;

    // Complemented outputs for the AND and OR gates
    wire q0_n, q1_n, q2_n;

    // Assign complemented outputs
    assign q0_n = ~q0;
    assign q1_n = ~q1;
    assign q2_n = ~q2;

    // Wire definitions for gate outputs (D inputs)
    wire d0, d1, d2;

    // Gate connections
    // XOR: second input is q0 -> d0 = x ^ q0
    // AND: second input is ~q1 -> d1 = x & ~q1
    // OR:  second input is ~q2 -> d2 = x | ~q2

    assign d0 = x ^ q0;
    assign d1 = x & q1_n; // q1_n is ~q1
    assign d2 = x | q2_n; // q2_n is ~q2

    // Flip-Flop updates
    always @(posedge clk) begin
        // The specification says: "Assume that the D flip-flops are 
        // initially reset to zero before the machine begins."
        // We model this with an initial block or a reset signal.
        // Since the port list only has clk, x, z, we assume reset is
        // handled externally or we initialize in an initial block for simulation.
        // For synthesis, if no reset pin is provided, the flip-flops
        // may power up to unknown values, but simulation initial values
        // are typically 0.

        // Update the flip-flops with the D inputs on the positive edge
        q0 <= d0;
        q1 <= d1;
        q2 <= d2;
    end

    // Output Z: three-input NOR gate
    // Inputs: q0, q1, q2 (the flip-flop outputs)
    // The specification: "the flip-flop outputs all go to a three-input NOR gate, whose output is Z"
    assign z = ~(q0 | q1 | q2);

