    // Internal register for the BCD counter (16 bits)
    reg [15:0] count;

    // Assign the 3-bit enable output
    // ena[0] enables the tens digit (q[7:4])
    // ena[1] enables the hundreds digit (q[11:8])
    // ena[2] enables the thousands digit (q[15:12])
    assign ena = {count[11:8] == 4'd9, count[15:12] == 4'd9, count[7:4] == 4'd9};

    // Synchronous always block for the counter
    always @(posedge clk or posedge reset) begin
        if (reset)
            count <= 16'd0;
        else begin
            // BCD increment logic
            // If the current count is 9999, roll over to 0
            if (count == 16'd9999)
                count <= 16'd0;
            else begin
                // Step 1: Add 1 to the LSB
                count <= count + 16'd1;

                // Step 2: Correct BCD digits that overflowed (>= 10)
                // Correction for ones digit (q[3:0])
                if (count[3:0] > 4'd9)
                    count[3:0] <= count[3:0] + 4'd6;

                // Correction for tens digit (q[7:4])
                if (count[7:4] > 4'd9)
                    count[7:4] <= count[7:4] + 4'd6;

                // Correction for hundreds digit (q[11:8])
                if (count[11:8] > 4'd9)
                    count[11:8] <= count[11:8] + 4'd6;

                // Correction for thousands digit (q[15:12])
                if (count[15:12] > 4'd9)
                    count[15:12] <= count[15:12] + 4'd6;
            end
        end
    end

