module TopModule (
    input  d,
    input  done_counting,
    input  ack,
    input  state [9:0],
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

    // Internal wires for decoded state signals
    wire s, s1, s11, s110, b0, b1, b2, b3, count, wait_state;

    // One-hot decoding
    assign s       = state[0];
    assign s1      = state[1];
    assign s11     = state[2];
    assign s110    = state[3];
    assign b0      = state[4];
    assign b1      = state[5];
    assign b2      = state[6];
    assign b3      = state[7];
    assign count   = state[8];
    assign wait_state = state[9];

    // ---------- Next-state generation (combinational) ----------
    // S next-state: from S (d=0), S1 (d=0), Wait (ack=1), S110 (d=0)
    assign S_next = (s & ~d) | (s1 & ~d) | (wait_state & ack) | (s110 & ~d);

    // S1 next-state: from S (d=1), S1 (d=1), S11 (d=1)
    assign S1_next = (s & d) | (s1 & d) | (s11 & d);

    // B3_next: asserted when next state is B3 (current state is B2, always goes to B3)
    assign B3_next = b2;

    // Count_next: asserted when next state is Count (current state is B3, always goes to Count)
    assign Count_next = b3;

    // Wait_next: asserted when next state is Wait (current state is Count and done_counting == 1)
    assign Wait_next = count & done_counting;

    // ---------- Output logic ----------
    // shift_ena: asserted in states B0, B1, B2, B3 (always 1 during those transitions)
    assign shift_ena = b0 | b1 | b2 | b3;

    // counting: asserted in state Count
    assign counting = count;

    // done: asserted in state Wait (as per diagram: Wait (done=1))
    assign done = wait_state;

endmodule

