module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    // Internal state registers
    reg [1:0] state; // 00: below s[0], 01: between s[1] and s[0], 10: between s[2] and s[1], 11: above s[2]
    reg [2:0] prev_s; // Previous sensor state to determine level change direction

    // Combinational logic for outputs based on current state, sensor inputs, and reset
    always @(*) begin
        // Default assignments (safe state)
        fr0 = 1'b0;
        fr1 = 1'b0;
        fr2 = 1'b0;
        dfr = 1'b0;

        // Active-high synchronous reset: assert all four outputs
        if (reset) begin
            fr0 = 1'b1;
            fr1 = 1'b1;
            fr2 = 1'b1;
            dfr = 1'b1;
            // State and prev_s are not strictly needed to be reset here for output logic,
            // but we keep them consistent with the spec "equivalent to water level low for a long time".
            // The spec says: "resets the state machine to a state equivalent to if the water level had been low for a long time 
            // (no sensors asserted, and all four outputs asserted)".
            // We set state to 00 and prev_s to 000 to match "no sensors asserted".
            // However, since this is an always @(*) block, state/prev_s are not updated here 
            // (they are updated in the sequential block). The outputs are the primary concern here.
        end else begin
            // Determine dfr based on level change: 
            // dfr is 1 if the current level (s) is higher than the previous level (prev_s)
            // We compare the highest asserted sensor bit.
            if (s > prev_s) begin
                dfr = 1'b1;
            end else begin
                dfr = 1'b0;
            end

            case (state)
                2'b00: begin
                    // Below s[0]: Maximum flow. fr0, fr1, fr2 asserted.
                    fr0 = 1'b1;
                    fr1 = 1'b1;
                    fr2 = 1'b1;
                    // dfr is already set above based on transition logic
                end
                2'b01: begin
                    // Between s[1] and s[0]: Table: fr0, fr1
                    fr0 = 1'b1;
                    fr1 = 1'b1;
                end
                2'b10: begin
                    // Between s[2] and s[1]: Table: fr0
                    fr0 = 1'b1;
                end
                2'b11: begin
                    // Above s[2]: Table: None
                    // All outputs remain 0 (already default assigned)
                end
            endcase
        end
    end

    // Synchronous reset and state update
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            // Reset state: equivalent to water level low for a long time
            // "no sensors asserted, and all four outputs asserted"
            state <= 2'b00;
            prev_s <= 3'b000;
        end else begin
            // Determine new state based on sensors s
            // Sensor mapping: s[2] highest, s[1] middle, s[0] lowest
            if (s[2]) begin
                // Above highest sensor
                state <= 2'b11;
            end else if (s[1]) begin
                // Between s[2] and s[1] (s[2] is 0, s[1] is 1)
                state <= 2'b10;
            end else if (s[0]) begin
                // Between s[1] and s[0] (s[1] is 0, s[0] is 1)
                state <= 2'b01;
            end else begin
                // Below lowest sensor (s[0] is 0)
                state <= 2'b00;
            end
            // Update previous sensor state
            prev_s <= s;
        end
    end

endmodule

